(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,14344,e=>{"use strict";e.s(["BYZ_COUNCILS",0,[{name:"ניקיאה הראשונה",year:"325",place:"ניקיאה (איזניק)",decision:"דחיית אריוס; האב והבן 'מאותה מהות'. מעמד כבוד לבישוף ירושלים."},{name:"קונסטנטינופול הראשונה",year:"381",place:"קונסטנטינופול",decision:"השלמת 'אני מאמין' הניקאי ומעמד רוח הקודש; לקונסטנטינופול — מקום שני אחרי רומא."},{name:"אפסוס",year:"431",place:"אפסוס",decision:"מרים 'תאוטוקוס' — יולדת האל; דחיית נסטוריוס."},{name:"חלקדון",year:"451",place:"חלקדון",decision:"שני טבעים בישוע; פרישת המונופיזיטים. ירושלים — פטריארכיה."},{name:"קונסטנטינופול השנייה",year:"553",place:"קונסטנטינופול",decision:"בימי יוסטיניאנוס; ניסיון לפשר עם המונופיזיטים, וגינוי כתבי אוריגנס."}],"BYZ_EMPERORS",0,[{name:"קונסטנטינוס הגדול",greek:"ΚΩΝΣΤΑΝΤΙΝΟΣ",reign:"306–337",note:"גשר מולוויאן, צו מילאנו, ניקיאה, קונסטנטינופוליס, וכנסיות הקבר, המולד ואלאונה עם אמו הלנה."},{name:"קונסטנטיוס השני",greek:"ΚΩΝΣΤΑΝΤΙΟΣ",reign:"337–361",note:"בימיו מרד גאלוס (351) והחקיקה האנטי־יהודית הראשונה."},{name:"יוליאנוס",greek:"ΙΟΥΛΙΑΝΟΣ",reign:"361–363",note:"'הכופר': ניסה להחזיר את הפגניות ויזם בניין מחדש של המקדש."},{name:"תאודוסיוס הראשון",greek:"ΘΕΟΔΟΣΙΟΣ Α",reign:"379–395",note:"הנצרות דת המדינה (380); עם מותו התפצלה האימפריה (395)."},{name:"תאודוסיוס השני",greek:"ΘΕΟΔΟΣΙΟΣ Β",reign:"408–450",note:"בימיו בוטלה הנשיאות (סביב 429). אשתו אבדוקיה פעלה בירושלים."},{name:"זנון",greek:"ΖΗΝΩΝ",reign:"474–491",note:"דיכא את מרד השומרונים (484) ובנה כנסייה על הר גריזים."},{name:"יוסטיניאנוס",greek:"ΙΟΥΣΤΙΝΙΑΝΟΣ",reign:"527–565",note:"מרד השומרונים (529), הניאה, כנסיית המולד המחודשת, סנטה קתרינה, קודקס החוקים."},{name:"הרקליוס",greek:"ΗΡΑΚΛΕΙΟΣ",reign:"610–641",note:"הביס את פרס והשיב את הצלב (630); בימיו נכבשה הארץ בידי המוסלמים."}],"BYZ_ERAS",0,[{id:"holyland",title:"קונסטנטינוס וארץ הקודש",range:"324–337",greek:"ΑΓΙΑ ΓΗ",note:"הקיסר הנוצרי הראשון שולט במזרח. כנסיות הקבר והמולד, קונסטנטינופוליס והצליין הראשון."},{id:"contest",title:"בין הצלב לאלים",range:"337–395",greek:"ΙΟΥΛΙΑΝΟΣ",note:"מרד גאלוס, יוליאנוס וניסיון בניין המקדש, והנצרות נעשית דת המדינה."},{id:"churches",title:"מאה של כנסיות ומדבר",range:"395–527",greek:"ΕΡΗΜΟΣ",note:"התלמוד הירושלמי, ביטול הנשיאות, אבדוקיה, חלקדון, מנזרי המדבר ופריחת בתי הכנסת והנגב."},{id:"justinian",title:"תור הזהב של יוסטיניאנוס",range:"527–565",greek:"ΙΟΥΣΤΙΝΙΑΝΟΣ",note:"מרד השומרונים, הניאה, כנסיית המולד המחודשת, סנטה קתרינה ומפת מידבא."},{id:"end",title:"אש מן המזרח",range:"565–641",greek:"ΤΕΛΟΣ",note:"הפלישה הפרסית, השבת הצלב, ובסוף — ירמוך וכניעת ירושלים למוסלמים."}],"BYZ_EVENTS",0,[{id:"BY-001",era:"holyland",year:324,date:"324",title:"קונסטנטינוס שולט במזרח",kind:"empire",key:!0,summary:"תחילת התקופה הביזנטית בארץ — המשך האימפריה הרומית, שהתנצרה.",body:"אחרי ניצחונו על ליקיניוס נעשה קונסטנטינוס קיסר יחיד. אין כאן כיבוש: אותם אנשים, אותם קיסרים ואותה אימפריה — רק הדת והתרבות משתנות. הנצרות, שהייתה מותרת מאז צו מילאנו (313), נעשית דת מועדפת. ארץ ישראל הופכת ל'ארץ הקודש', וירושלים ל'הגיה פוליס' — העיר הקדושה.",tip:"התקופה הביזנטית בחלוקת הקורס: 324–638. השם 'ביזנטית' הוא מונח מודרני, מן העיר ביזנטיון."},{id:"BY-002",era:"holyland",year:325,date:"325",title:"ועידת ניקיאה",kind:"empire",key:!0,concept:!0,summary:"המועצה האקומנית הראשונה דוחה את הכפירה האריאנית.",body:"קונסטנטינוס כינס את הבישופים בניקיאה כדי להכריע במחלוקת על היחס בין האל האב לבן. אריוס, שטען שהבן נברא, הוכרז ככופר. נוצר דגם שיחזור: ועידה, הכרעה ורדיפת מי שלא מקבל אותה. לבישוף ירושלים, מקריוס, ניתנה בוועידה מעמד של כבוד.",tip:"ניקיאה (325) — אריוס; אפסוס (431) — מרים 'תאוטוקוס'; חלקדון (451) — הטבע האלוהי והאנושי."},{id:"BY-003",era:"holyland",year:326,date:"326",title:"מסע הלנה לארץ הקודש",kind:"pilgrim",key:!0,concept:!0,summary:"אם הקיסר מגיעה לארץ; נבנות כנסיות המולד ואלאונה.",body:"הלנה סיירה בארץ, ובעקבות ביקורה נבנו כנסיית המולד בבית לחם, מעל מערת הלידה, וכנסיית אלאונה (פטר נוסטר) על הר הזיתים, מעל מערת לימוד התלמידים. לפי המסורת מצאה את 'הצלב האמיתי' בירושלים.",tip:"מפעלי הדור של קונסטנטינוס: כנסיית הקבר, כנסיית המולד, אלאונה ואלוני ממרא.",sites:"בית לחם, הר הזיתים"},{id:"BY-004",era:"holyland",year:330,date:"330",title:"חנוכת קונסטנטינופוליס",kind:"empire",concept:!0,summary:"בירה חדשה — 'רומא החדשה' — במקום ביזנטיון.",body:"קונסטנטינוס השלים את בניית הבירה במקום העיר היוונית ביזנטיון, על הבוספורוס. מכאן גזרו חוקרים מודרניים את השם 'האימפריה הביזנטית'. היום — איסטנבול.",tip:"330 = קונסטנטינופוליס; 325 = ניקיאה; 324 = תחילת התקופה. שלוש שנים סמוכות — כדאי לזכור את הסדר."},{id:"BY-005",era:"holyland",year:330,date:"סביב 330",title:"הלאורה הראשונה במדבר יהודה",kind:"church",summary:"חריטון מייסד את לאורת פארן בעין פרת.",body:"הנזיר חריטון, שהגיע מאסיה הקטנה, ייסד את הלאורה הראשונה — קהילת נזירים שחיו בתאים נפרדים והתכנסו בסוף השבוע — בנחל פרת. זו ראשיתה של תנועת הנזירות שתהפוך את מדבר יהודה ל'עיר' של מנזרים.",tip:"לאורה: תאים מפוזרים לאורך נחל ותפילה משותפת בשבת. קינוביון: מנזר שבו חיים יחד.",sites:"עין פרת (נחל פרת)"},{id:"BY-006",era:"holyland",year:333,date:"333",title:"הצליין מבורדו",kind:"pilgrim",concept:!0,summary:"יומן המסע הנוצרי הקדום ביותר לארץ.",body:"צליין אנונימי מבורדו שבגאליה תיעד את מסלולו לירושלים ובחזרה, עם רשימת התחנות והמרחקים ותיאור קצר של המקומות הקדושים. הוא ראה את כנסיית הקבר בבנייתה ותיאר את הר הבית החרב.",tip:"333 — הצליין מבורדו; 381–384 — אגריה. שני היומנים הם מקורות למקומות הקדושים."},{id:"BY-007",era:"holyland",year:335,date:"335",title:"חנוכת כנסיית הקבר",kind:"church",key:!0,concept:!0,summary:"על מקום הצליבה והקבר, במקום מקדש ונוס של איליה.",body:"קונסטנטינוס ציווה להרוס את המקדש של אדריאנוס ולחשוף את הקבר. המתחם כלל בסיליקה (המרטיריון), חצר עם סלע הגולגולתא, ומבנה עגול מעל הקבר — הרוטונדה (האנסטסיס), שהושלם מעט אחר כך. הכנסייה נחנכה ב־335.",tip:"כנסיית הקבר משלבת שני טיפוסים: בסיליקה ומבנה מרכזי עגול סביב מוקד מקודש.",sites:"כנסיית הקבר, העיר העתיקה"},{id:"BY-008",era:"holyland",year:337,date:"337",title:"קונסטנטינוס מוטבל ומת",kind:"empire",summary:"הקיסר שהעדיף את הנצרות מוטבל רק על ערש דווי.",body:"קונסטנטינוס הוטבל סמוך למותו. ירשו אותו בניו, ובמזרח שלט קונסטנטיוס השני (337–361). בימיו החלה החקיקה האנטי־יהודית: איסור על יהודים להחזיק עבדים נוצרים ולהינשא לנוצרים.",tip:"הוטבל ב־337 — לא אחרי מולוויאן (312) ולא בניקיאה (325)."},{id:"BY-009",era:"contest",year:350,date:"המאה ה־4",title:"בית הכנסת בחמת טבריה",kind:"jewish",concept:!0,summary:"גלגל המזלות המוקדם ביותר שנמצא בבית כנסת בארץ.",body:"בבית הכנסת של סוורוס בחמת טבריה רצפת פסיפס בשלושה חלקים: ארון קודש בין מנורות ותשמישי קדושה, גלגל המזלות ובמרכזו הליוס במרכבתו, וכתובות הקדשה ביוונית. בבית שני כמעט נמנעו מדמויות; בתקופה הביזנטית — כשהאיום הוא הנצרות ולא עבודת האלילים — הרסן השתחרר.",tip:"גלגלי מזלות בבתי כנסת: חמת טבריה (מאה 4), ציפורי (מאה 5), בית אלפא (מאה 6), נערן, סוסיא. בעין גדי — רק שמות המזלות, בלי ציור.",sites:"גן לאומי חמת טבריה"},{id:"BY-010",era:"contest",year:351,date:"351–352",title:"מרד גאלוס",kind:"war",concept:!0,summary:"מרד יהודי בציפורי, בטבריה ובלוד, שנקרא על שם מדכאו.",body:"בימי קונסטנטיוס השני פרץ מרד יהודי שמרכזו בציפורי. דיכא אותו קונסטנטיוס גאלוס, ועל שמו נקרא — כמו פולמוס של ורוס ופולמוס של קיטוס. לפי ההרצאה לא היו לו השלכות ארוכות טווח.",tip:"גאלוס — 351, ציפורי. אל תחליפו עם מרד השומרונים (484, 529).",sites:"ציפורי, טבריה, לוד"},{id:"BY-011",era:"contest",year:362,date:"361–363",title:"יוליאנוס הכופר",kind:"empire",key:!0,concept:!0,summary:"הקיסר שניסה להחזיר את הפגניות — ויזם בניין מחדש של המקדש בירושלים.",body:"יוליאנוס ביטל את זכויות היתר של הנצרות וחידש את המקדשים הפגניים. הוא ראה ביהודים בני ברית נגד הנוצרים ('אויב אויבי') והתיר לבנות מחדש את בית המקדש. העבודות החלו, אך נפסקו — לפי המקורות בגלל אש שפרצה ממעמקי האדמה — ויוליאנוס נהרג במלחמה בפרסים ב־363.",tip:"ההרצאה מציגה את ניסיון בניין המקדש כ'אנקדוטה'. אל תבלבלו עם יוליאנוס בן סבר, מנהיג מרד השומרונים (529)."},{id:"BY-012",era:"contest",year:363,date:"363",title:"רעידת האדמה של 363",kind:"war",summary:"רעש חזק פוגע בגליל, בבית שאן ובפטרה.",body:"במאי 363 פקדה את האזור רעידת אדמה קשה שגרמה נזק בערים רבות, בהן ציפורי, בית שאן ופטרה. המקורות הנוצריים קשרו אותה לכישלון בניין המקדש של יוליאנוס.",tip:"אל תבלבלו עם רעידת האדמה הגדולה של 749, שהחריבה את בית שאן בתקופה האומיית.",sites:"ציפורי, בית שאן"},{id:"BY-013",era:"contest",year:380,date:"380",title:"הנצרות — דת המדינה",kind:"empire",key:!0,concept:!0,summary:"צו תאודוסיוס הראשון; הנצרות הופכת מדת נרדפת לדת רודפת.",body:"תאודוסיוס הראשון הכריז על הנצרות הניקאית כדת הרשמית היחידה, ובשנים 391–392 אסר על קורבנות ופולחן פגאני. מכאן נרדפים יהודים, שומרונים ופגאנים, וגוברת החקיקה נגדם.",tip:"מותרת — 313; מועדפת — 324; דת המדינה — 380."},{id:"BY-014",era:"contest",year:383,date:"381–384",title:"יומן המסע של אגריה",kind:"pilgrim",concept:!0,summary:"צליינית מן המערב מתארת את הליטורגיה של ירושלים.",body:"אגריה (איתריה), כנראה אצילה או נזירה מספרד או מגאליה, סיירה בארץ, בסיני ובמצרים, וכתבה לאחיותיה יומן מפורט. בו תיאורים של תפילות השבוע הקדוש וחג הפסחא בירושלים, ושל המקומות שבהם ביקרה.",tip:"אגריה מתעדת טקסים ומנהגים; הצליין מבורדו (333) — מסלול ותחנות."},{id:"BY-015",era:"contest",year:386,date:"386",title:"הירונימוס מתיישב בבית לחם",kind:"church",summary:"תרגום התנ״ך ללטינית — הוולגטה — נעשה במערה ליד מערת הלידה.",body:"הירונימוס הגיע לבית לחם עם הגבירה פאולה, וייסדו שם מנזרים. בעזרת מורים יהודים תרגם את התנ״ך מעברית ללטינית — הוולגטה, התרגום הרשמי של הכנסייה הקתולית. מערת הירונימוס מוצגת מתחת לכנסיית סנט קתרין הצמודה לכנסיית המולד.",tip:"פרט שקבוצות קתוליות מכירות: בחצר כנסיית סנט קתרין בבית לחם עומד פסלו של הירונימוס.",sites:"בית לחם, כנסיית המולד"},{id:"BY-016",era:"contest",year:390,date:"סוף המאה ה־4",title:"שלוש פלאיסטינות",kind:"empire",concept:!0,summary:"הארץ מחולקת לשלוש פרובינציות.",body:"בסוף המאה ה־4 ובתחילת ה־5 חולקה הארץ: פלאיסטינה פרימה — מרכז הארץ, בירתה קיסריה; פלאיסטינה סקונדה — הגליל והעמקים, בירתה בית שאן (סקיתופוליס); פלאיסטינה טרטיה (סלוטריס) — הנגב ועבר הירדן הדרומי.",tip:"פרימה — קיסריה; סקונדה — בית שאן. בהרצאה צוינה חלוצה כבירת טרטיה; במקורות המקובלים בירתה היא פטרה."},{id:"BY-017",era:"contest",year:395,date:"395",title:"פיצול האימפריה",kind:"empire",concept:!0,summary:"עם מות תאודוסיוס — מזרח ומערב לתמיד.",body:"בניו של תאודוסיוס קיבלו כל אחד חצי. המערב נפל לברברים פחות ממאה שנה אחר כך (476). 'האימפריה הביזנטית' היא החלק המזרחי, שימשיך להתקיים עד 1453.",tip:"395 — פיצול; 476 — נפילת המערב; 1453 — נפילת קונסטנטינופוליס בידי העות'מאנים."},{id:"BY-018",era:"churches",year:400,date:"סביב 400",title:"חתימת התלמוד הירושלמי",kind:"jewish",key:!0,summary:"בטבריה — כמאה שנה לפני חתימת התלמוד הבבלי.",body:"התלמוד הירושלמי, שנערך בעיקר בטבריה, נחתם בתנאים קשים של שלטון נוצרי עוין, ולכן הוא קצר ופחות ערוך מן הבבלי (סביב 500). בכך מסתיימת 'תקופת התלמוד' — שחופפת רק בחלקה לתקופה הביזנטית.",tip:"משנה — ציפורי, סביב 200; ירושלמי — טבריה, סביב 400; בבלי — בבל, סביב 500.",sites:"טבריה"},{id:"BY-019",era:"churches",year:400,date:"המאות ה־4–5",title:"בתי הכנסת הגליליים — בתארוך חדש",kind:"jewish",concept:!0,summary:"כפר נחום וברעם התבררו כמאוחרים — וכך התערערה החלוקה ל'קדומים' ו'מאוחרים'.",body:"בעבר חילקו את בתי הכנסת ל'קדומים' (גליליים, חזית לירושלים, רצפת אבן), 'מאוחרים' (בסיליקליים, אפסיס ופסיפס) ו'בינוניים'. מטבעות מן המאה ה־5 מתחת לרצפת בית הכנסת הלבן בכפר נחום הוכיחו שגם הוא מן התקופה הביזנטית. היום מקובלת חלוקה אזורית: גליליים, גולניים, דמויי כנסייה ודרום הר חברון.",tip:"השוני משקף אזור ולא זמן — זו המסקנה המחקרית העדכנית.",sites:"כפר נחום, ברעם, אום אל־קנאטיר"},{id:"BY-020",era:"churches",year:428,date:"405–473",title:"אבתימיוס ונזירות המדבר",kind:"church",summary:"לאורת אבתימיוס (428) — לב תנועת הנזירים במדבר יהודה.",body:"אבתימיוס הגיע לארץ ב־405, ייסד ב־428 לאורה במישור אדומים, והפך לדמות מרכזית של הנזירות. תלמידיו, ובהם סבס, ייסדו עשרות מנזרים. במישור אדומים אפשר לבקר במנזר אבתימיוס ובמנזר מרטיריוס.",tip:"במנזר מרטיריוס במעלה אדומים — פסיפסים, מרחץ ואכסניה לצליינים.",sites:"מנזר אבתימיוס, מנזר מרטיריוס"},{id:"BY-021",era:"churches",year:429,date:"סביב 429",title:"ביטול הנשיאות",kind:"jewish",key:!0,concept:!0,summary:"הנשיא האחרון, רבן גמליאל השישי, מת — והשלטון אינו ממנה מחליף.",body:"בימי תאודוסיוס השני בוטל מוסד הנשיאות, שהנהיג את יהודי הארץ מאז יבנה. יחד עם החקיקה המפלה, המיסים וההגירה, זה החליש מאוד את ההנהגה היהודית בארץ, ומרכז הכובד עבר בהדרגה לבבל.",tip:"גורמי התמעטות היהודים בארץ לפי ההרצאה: הרג במרידות, מיסוי והגירה, וחקיקה ביזנטית — לא גלות המונית ב־70."},{id:"BY-022",era:"churches",year:431,date:"431",title:"ועידת אפסוס — מרים 'תאוטוקוס'",kind:"empire",concept:!0,summary:"מרים מוכרזת 'יולדת האל', ולא רק 'יולדת המשיח'.",body:"נסטוריוס הציע לכנות את מרים 'כריסטוטוקוס'; הוועידה דחתה זאת וקבעה 'תאוטוקוס'. ההחלטה הגבירה את פולחן מרים, ובעקבותיה נבנו כנסיות על שמה — כמו הקטיסמה בדרך לבית לחם וכנסיית התאוטוקוס על הר גריזים.",tip:"תאוטוקוס = יולדת האל; כריסטוטוקוס = יולדת המשיח."},{id:"BY-023",era:"churches",year:444,date:"438–460",title:"הקיסרית אבדוקיה בירושלים",kind:"pilgrim",key:!0,concept:!0,summary:"חומה דרומית, כנסיית סטפנוס ושיר הלל לחמת גדר.",body:"אבדוקיה, אשת תאודוסיוס השני, ביקרה בירושלים ב־438 והשתקעה בה כעבור שנים אחדות עד מותה (460). היא הרחיבה את חומת העיר דרומה כך שתכלול את הר ציון ועיר דוד, העלתה את עצמות סטפנוס — המעונה הראשון — ובנתה לו כנסייה מצפון לשער שכם. בחמת גדר נמצא שיר הלל שחיברה למרחצאות.",tip:"כנסיית סטפנוס של אבדוקיה מזוהה עם מתחם סנט אטיין (האקול ביבליק).",sites:"סנט אטיין, הר ציון, חמת גדר"},{id:"BY-024",era:"churches",year:451,date:"451",title:"ועידת חלקדון; ירושלים פטריארכיה",kind:"empire",key:!0,concept:!0,summary:"המחלוקת המונופיזיטית מפלגת את הכנסייה; ירושלים מוכרזת פטריארכיה.",body:"הוועידה קבעה שלישוע שני טבעים — אלוהי ואנושי. המונופיזיטים, שראו בו טבע אחד, נפרדו (מהם הכנסיות הקופטית, הארמנית והסורית). הבישוף יובנאליס קיבל לירושלים מעמד של פטריארכיה — לצד רומא, קונסטנטינופול, אלכסנדריה ואנטיוכיה. נזירי הארץ מרדו נגדו בתחילה.",tip:"הכנסיות הלא־כלקדוניות (קופטים, ארמנים, סורים, אתיופים) נוכחות עד היום בכנסיית הקבר."},{id:"BY-025",era:"churches",year:456,date:"סביב 456",title:"כנסיית הקטיסמה",kind:"church",concept:!0,summary:"כנסייה מתומנת על הסלע שעליו נחה מרים בדרך לבית לחם.",body:"הכנסייה, שהקימה הגבירה איקליה, בנויה סביב סלע שלפי המסורת ישבה עליו מרים — 'קטיסמה' ביוונית: מושב. התוכנית המרכזית המתומנת אופיינית לכנסיות הנצחה שנבנו סביב מוקד מקודש.",tip:"שני טיפוסי כנסיות: בסיליקה (אורכית, כמו כורסי) ומבנה מרכזי (מתומן או עגול, כמו הקטיסמה והרוטונדה בכנסיית הקבר).",sites:"כנסיית הקטיסמה (ליד מנזר מר אליאס)"},{id:"BY-026",era:"churches",year:483,date:"483",title:"סבס מייסד את מר סבא",kind:"church",summary:"'הלאורה הגדולה' בנחל קדרון — פעילה עד היום.",body:"סבס, תלמיד אבתימיוס, ייסד את הלאורה הגדולה במצוקי נחל קדרון. המנזר — מר סבא — מאוכלס ברציפות עד היום, ונשים אינן נכנסות אליו. סבס היה דמות פוליטית חשובה, ושלח שליחויות לקיסר.",tip:"מר סבא הוא מן המנזרים העתיקים בעולם שפעילים ברציפות.",sites:"מר סבא, נחל קדרון"},{id:"BY-027",era:"churches",year:484,date:"484",title:"מרד השומרונים בימי זנון",kind:"war",concept:!0,summary:"המורדים פוגעים בנוצרים בשכם; על הר גריזים נבנית כנסייה.",body:"השומרונים מרדו נגד הרדיפה הביזנטית והכתירו מלך. הקיסר זנון דיכא אותם, גירשם מהר גריזים ובנה על פסגתו כנסייה מתומנת למרים (התאוטוקוס).",tip:"על הר גריזים רואים את שרידי הכנסייה המתומנת של זנון לצד שרידי המקדש השומרוני מן התקופה ההלניסטית.",sites:"הר גריזים"},{id:"BY-028",era:"churches",year:500,date:"המאות ה־5–6",title:"שגשוג ערי הנגב",kind:"church",summary:"שבטה, עבדת, ניצנה וחלוצה — חקלאות מדבר, יין וכנסיות.",body:"ערי דרך הבשמים הנבטיות הגיעו לשיא בתקופה הביזנטית: כנסיות רבות, חקלאות בשיטת קציר נגר, וגתות ליין שיוצא דרך נמל עזה ('יין עזה'). פפירוסי ניצנה מתעדים את חיי היום־יום.",tip:"בשבטה שלוש כנסיות ובתים שמורים; בעבדת — גתות, כנסיות ובית מרחץ.",sites:"שבטה, עבדת, ניצנה, חלוצה"},{id:"BY-029",era:"justinian",year:527,date:"527",title:"יוסטיניאנוס עולה לשלטון",kind:"empire",key:!0,summary:"קיסר ריכוזי, בנאי גדול ומחוקק — וגרוע מכולם ליהודים ולשומרונים.",body:"יוסטיניאנוס (527–565) קידד את המשפט הרומי (קודקס יוסטיניאנוס), בנה את איה סופיה בקונסטנטינופול ושורת כנסיות בארץ, והחריף את החקיקה נגד יהודים ושומרונים — כולל התערבות בסדרי בית הכנסת.",tip:"מפעלי יוסטיניאנוס בארץ: הניאה, כנסיית המולד המחודשת, הארכת הקרדו, מנזר סנטה קתרינה בסיני."},{id:"BY-030",era:"justinian",year:529,date:"529",title:"מרד השומרונים — יוליאנוס בן סבר",kind:"war",key:!0,concept:!0,summary:"המרד הגדול של השומרונים; הדיכוי פוגע בעם כולו.",body:"יוליאנוס בן סבר הוכתר למלך, והמורדים פגעו בנוצרים ובכנסיות — גם בבית לחם. הדיכוי היה אכזרי: עשרות אלפים נהרגו או נמכרו לעבדות, והעם השומרוני לא התאושש ממנו. מרד נוסף פרץ ב־556 בקיסריה.",tip:"שני מרידות שומרוניות: 484 (זנון) ו־529 (יוסטיניאנוס, יוליאנוס בן סבר)."},{id:"BY-031",era:"justinian",year:535,date:"שנות ה־30 של המאה ה־6",title:"כנסיית המולד נבנית מחדש",kind:"church",key:!0,summary:"הבסיליקה של יוסטיניאנוס — עומדת עד היום.",body:"אחרי נזקי מרד השומרונים בנה יוסטיניאנוס את כנסיית המולד מחדש, גדולה מקודמתה של קונסטנטינוס ועם סיום משולש (טריקונכוס) מעל מערת הלידה. לפי המסורת, הפרסים לא החריבו אותה ב־614 בזכות פסיפס המגושים בלבוש פרסי שעל חזיתה.",tip:"כנסיית המולד היא הכנסייה הפעילה העתיקה ביותר בארץ. מתחת לרצפה רואים את פסיפסי הכנסייה הקונסטנטינית.",sites:"כנסיית המולד, בית לחם"},{id:"BY-032",era:"justinian",year:541,date:"541–542",title:"מגפת יוסטיניאנוס",kind:"war",summary:"מגפת הדבר הראשונה המתועדת, דרך נמלי מצרים.",body:"המגפה הגיעה מנמלי מצרים, התפשטה לארץ ולקונסטנטינופול והרגה חלק ניכר מן האוכלוסייה. היא חזרה בגלים במשך כמאתיים שנה והחלישה את האימפריה ערב הפלישות.",tip:"ידע כללי: אחד ההסברים לנסיגה הדמוגרפית והכלכלית בסוף התקופה."},{id:"BY-033",era:"justinian",year:543,date:"543",title:"חנוכת כנסיית הניאה",kind:"church",key:!0,concept:!0,summary:"'החדשה' — כנסיית הענק של יוסטיניאנוס למרים, בדרום העיר.",body:"הניאה (מריה נאה) נבנתה על מדרון הר ציון, על מסדים וקמרונות עצומים, ונחנכה ב־543. בחפירות ליד החומה הדרומית של הרובע היהודי נחשפו חלקים ממנה ובור מים ענקי ובו כתובת הקדשה של יוסטיניאנוס. כדי לחבר אותה לעיר הוארך הקרדו המערבי דרומה.",tip:"הניאה מופיעה במפת מידבא. בקרדו ברובע היהודי מהלכים על הקטע שנבנה בימי יוסטיניאנוס.",sites:"הרובע היהודי, הקרדו"},{id:"BY-034",era:"justinian",year:550,date:"המאה ה־6",title:"בית הכנסת בבית אלפא",kind:"jewish",concept:!0,summary:"פסיפס עממי: עקדת יצחק, גלגל המזלות וארון הקודש.",body:"בית הכנסת, מטיפוס 'דמוי כנסייה' עם אפסיס, התגלה ב־1928 בקיבוץ חפציבה. ברצפה שלושה לוחות: עקדת יצחק — ובה האיל קשור לעץ — גלגל המזלות והליוס, וארון הקודש בין מנורות. כתובת ארמית מתארכת אותו לימי הקיסר יוסטינוס, ונזכרים בה האומנים מריאנוס וחנינא.",tip:"בית אלפא שייך לטיפוס הבסיליקלי, 'דמוי כנסייה'. אל תבלבלו עם 'כתובת חפציבה' הסלווקית שנמצאה באותו אזור.",sites:"בית אלפא (חפציבה)"},{id:"BY-035",era:"justinian",year:556,date:"548–565",title:"מנזר סנטה קתרינה בסיני",kind:"church",summary:"מנזר מבוצר למרגלות הר משה, ליד מקום 'הסנה הבוער'.",body:"יוסטיניאנוס הקים מנזר מבוצר לנזירים שחיו סביב מקום הסנה הבוער. בכנסייה פסיפס ההשתנות המפורסם, ובספרייה כתבי יד עתיקים ואוסף איקונות — מהיחידים ששרדו את מחלוקת האיקונות.",tip:"המנזר הוא מן העתיקים בעולם שפעילים ברציפות — מאז המאה ה־6.",sites:"סנטה קתרינה (סיני)"},{id:"BY-036",era:"justinian",year:560,date:"המאה ה־6",title:"מפת מידבא",kind:"pilgrim",key:!0,concept:!0,summary:"מפת פסיפס של ארץ הקודש, וירושלים הביזנטית במרכזה.",body:"המפה נמצאה ב־1884 ברצפת כנסייה במידבא שבעבר הירדן. היא מכוונת מזרחה, נשענת על האונומסטיקון של אאוזביוס, ומציגה את ירושלים בקנה מידה מוגדל: שער שכם עם העמוד, הקרדו, כנסיית הקבר והניאה. משום שהניאה מופיעה בה, היא מתוארכת לאחר 543.",tip:"מזרח בראש המפה. ירושלים מוגדלת — מרכז אידיאולוגי ולא מדידה מדויקת. העתק במרכז המבקרים של הקרדו.",sites:"מידבא (ירדן); העתק בקרדו בירושלים"},{id:"BY-037",era:"justinian",year:560,date:"המאות ה־6–7",title:"ברייתא דתחומין בבית הכנסת ברחוב",kind:"jewish",concept:!0,summary:"כתובת הפסיפס הארוכה בארץ — גבולות הארץ לעניין מצוות.",body:"ברצפת בית הכנסת ברחוב, דרומית לבית שאן, נמצאה כתובת עברית ארוכה המפרטת אילו יישובים פטורים או חייבים במעשרות ובשמיטה — הגדרה הלכתית של גבולות הארץ.",tip:"הברייתא היא טקסט הלכתי; מפת מידבא היא מפה נוצרית — לא לבלבל ביניהן.",sites:"תל רחוב (עמק בית שאן)"},{id:"BY-038",era:"end",year:570,date:"סביב 570",title:"הצליין מפיאצ'נצה",kind:"pilgrim",summary:"תיאור ארץ הקודש בשיא פריחתה, ערב הקריסה.",body:"צליין מפיאצ'נצה שבאיטליה תיאר מקומות קדושים, שרידים קדושים ('רליקוויות') וטקסים בשנות ה־70 של המאה ה־6. התיאור ממחיש את 'תעשיית' הצליינות — אכסניות, מזכרות ומסלולים קבועים.",tip:"צליינים: בורדו (333), אגריה (381–384), פיאצ'נצה (570). ומפת מידבא — מאותה רוח."},{id:"BY-039",era:"end",year:614,date:"614",title:"הכיבוש הפרסי של ירושלים",kind:"war",key:!0,concept:!0,summary:"הצבא הסאסאני כובש את העיר, טובח, שורף כנסיות ושובה את הצלב.",body:"הפרסים פלשו לארץ, ויהודים רבים הצטרפו אליהם בתקווה לגאולה. ירושלים נכבשה אחרי מצור; כנסיות נשרפו, תושבים נטבחו, ו'הצלב האמיתי' נלקח לפרס. במערת קבורה ליד בריכת ממילא נמצאו שרידי מאות קורבנות הטבח.",tip:"מערת ממילא, שנשמרה מתחת לבניין ליד בריכת ממילא, מכילה עצמות של מאות נוצרים שנטבחו ב־614.",sites:"ממילא, כנסיית הקבר"},{id:"BY-040",era:"end",year:617,date:"614–617",title:"שלטון יהודי קצר בירושלים",kind:"jewish",summary:"הפרסים מסרו את העיר ליהודים — ואחר כך חזרו בהם.",body:"לזמן קצר ניהלו יהודים את ירושלים בחסות הפרסים, ואולי חודשו בה תפילות על הר הבית. כעבור כשלוש שנים העדיפו הפרסים את הנוצרים, הרוב בארץ, והחזירו להם את השליטה.",tip:"השלטון היהודי לא היה 'לצמיתות' — רק כשלוש שנים."},{id:"BY-041",era:"end",year:630,date:"628–630",title:"הרקליוס משיב את הצלב",kind:"empire",key:!0,concept:!0,summary:"ניצחון על פרס, תהלוכה בירושלים — וגזירות על היהודים.",body:"הקיסר הרקליוס הביס את פרס, והשיב את הצלב לירושלים בתהלוכה חגיגית (630). בעקבות שיתוף הפעולה של היהודים עם הפרסים נטבחו יהודים ונגזר עליהם גירוש מירושלים. כמה שנים אחר כך הגיעו צבאות האסלאם.",tip:"השבת הצלב נחגגת בכנסייה ב'חג הצלב' (14 בספטמבר)."},{id:"BY-042",era:"end",year:634,date:"634",title:"קרב אג'נאדין",kind:"war",summary:"הניצחון המוסלמי הראשון הגדול על הביזנטים בארץ.",body:"צבאות הח'ליפות, בפיקוד ח'אלד אבן אל־וליד, הביסו צבא ביזנטי בשפלה, באזור בית גוברין. אחריו נפלו רוב ערי הארץ, למעט ירושלים וקיסריה.",tip:"סדר הקרבות: אג'נאדין (634) ← פחל ליד פלה (635) ← ירמוך (636)."},{id:"BY-043",era:"end",year:636,date:"636",title:"קרב ירמוך",kind:"war",key:!0,concept:!0,summary:"התבוסה המכרעת של הצבא הביזנטי — הארץ אבודה לביזנטים.",body:"בקרב בעמק הירמוך, בגבול הגולן של היום, הובס הצבא שהרקליוס שלח. האימפריה נסוגה מסוריה ומארץ ישראל.",tip:"ירמוך (636) — לא פרסים ולא שומרונים: הניצחון המכריע של המוסלמים."},{id:"BY-044",era:"end",year:638,date:"637/638",title:"ירושלים נכנעת לח'ליף עומר",kind:"war",key:!0,concept:!0,summary:"הפטריארך סופרוניוס מוסר את העיר — סוף התקופה הביזנטית בארץ.",body:"אחרי מצור מסר הפטריארך סופרוניוס את ירושלים לח'ליף עומר בן אל־ח'טאב, שהעניק לנוצרים הגנה. לפי מקורות יהודיים, הותר ליהודים לשוב ולהתגורר בעיר. בכך מתחילה התקופה המוסלמית הקדומה.",tip:"638 היא שנת הסיום של התקופה הביזנטית בחלוקת הקורס."},{id:"BY-045",era:"end",year:641,date:"640/641",title:"נפילת קיסריה",kind:"war",summary:"העיר הביזנטית האחרונה בארץ נכבשת אחרי מצור ארוך.",body:"קיסריה, בירת פלאיסטינה פרימה, החזיקה מעמד בזכות הים, שדרכו קיבלה אספקה. היא נפלה אחרי מצור ארוך — הסוף הסופי של השלטון הביזנטי בארץ.",tip:"קיסריה — העיר הראשונה בחשיבותה בתקופה הרומית והביזנטית — היא גם האחרונה שנפלה.",sites:"קיסריה"}],"BYZ_KINDS",0,[{id:"empire",title:"קיסרות ומועצות"},{id:"war",title:"מלחמות ומרידות"},{id:"jewish",title:"יהודים ובתי כנסת"},{id:"church",title:"כנסיות ומנזרים"},{id:"pilgrim",title:"צליינות וארץ הקודש"}],"BYZ_PILGRIMS",0,[{name:"הלנה",when:"326",note:"אם הקיסר; בעקבות ביקורה — כנסיות המולד ואלאונה. לפי המסורת מצאה את הצלב."},{name:"הצליין מבורדו",when:"333",note:"היומן הקדום ביותר: מסלול, תחנות ומרחקים."},{name:"אאוזביוס — האונומסטיקון",when:"תחילת המאה ה־4",note:"מילון שמות המקומות המקראיים והמרחקים ביניהם — מורה הדרך של הצליינים, ובסיס למפת מידבא."},{name:"אגריה",when:"381–384",note:"ליטורגיה, טקסים ומנהגים בירושלים ובאתרים הקדושים."},{name:"הירונימוס ופאולה",when:"386",note:"התיישבו בבית לחם; הוולגטה — תרגום התנ״ך ללטינית."},{name:"אבדוקיה",when:"438–460",note:"הקיסרית הצליינית: חומות, כנסיות והעלאת עצמות סטפנוס."},{name:"הצליין מפיאצ'נצה",when:"סביב 570",note:"ארץ הקודש בשיא פריחתה: רליקוויות, טקסים ואכסניות."},{name:"מפת מידבא",when:"המאה ה־6",note:"מפת פסיפס של ארץ הקודש — מעין 'מדריך' ויזואלי לצליין."}],"BYZ_SITES",0,[{name:"כנסיית הקבר",type:"church",what:"בסיליקה ורוטונדה (האנסטסיס) של קונסטנטינוס, 335. כיום — שש עדות נוצריות."},{name:"כנסיית המולד, בית לחם",type:"church",what:"הבסיליקה של יוסטיניאנוס מעל מערת הלידה, ופסיפסי הכנסייה הקונסטנטינית מתחת לרצפה."},{name:"אלאונה (פטר נוסטר)",type:"church",what:"כנסיית הלנה בהר הזיתים, מעל מערת לימוד התלמידים."},{name:"הניאה והקרדו",type:"church",what:"כנסיית יוסטיניאנוס (543) והקרדו שהוארך דרומה אליה, ברובע היהודי."},{name:"הקטיסמה",type:"church",what:"כנסייה מתומנת על הסלע שעליו נחה מרים, בדרך לבית לחם."},{name:"כורסי",type:"church",what:"בסיליקה שמורה ומנזר ממזרח לכנרת, במקום נס עדר החזירים."},{name:"טבחה",type:"church",what:"כנסיית הלחם והדגים ופסיפס הדגים והלחם המפורסם."},{name:"מר סבא",type:"monastery",what:"הלאורה הגדולה בנחל קדרון (483), פעילה עד היום."},{name:"מנזר מרטיריוס",type:"monastery",what:"מנזר קינוביון במעלה אדומים: פסיפסים, מרחץ ואכסניה."},{name:"סנטה קתרינה",type:"monastery",what:"מנזר יוסטיניאנוס בסיני, ליד מקום הסנה הבוער."},{name:"חמת טבריה",type:"synagogue",what:"גלגל המזלות המוקדם בארץ (מאה 4), בבית הכנסת של סוורוס."},{name:"בית אלפא",type:"synagogue",what:"פסיפס עקדת יצחק, גלגל המזלות וארון הקודש (מאה 6)."},{name:"ציפורי",type:"synagogue",what:"בית כנסת עם עקדה, גלגל מזלות ועבודת המקדש (מאה 5)."},{name:"כפר נחום",type:"synagogue",what:"בית הכנסת 'הלבן' הגלילי — התארוך המאוחר שלו שינה את המחקר."},{name:"רחוב",type:"synagogue",what:"כתובת 'ברייתא דתחומין' — גבולות הארץ לעניין מצוות."},{name:"אשתמוע וסוסיא",type:"synagogue",what:"בתי כנסת מטיפוס דרום הר חברון: אולם רחב וכניסה ממזרח."},{name:"שבטה, עבדת וניצנה",type:"city",what:"ערי הנגב בשיא פריחתן: כנסיות, גתות וחקלאות מדבר."},{name:"קיסריה",type:"city",what:"בירת פלאיסטינה פרימה: חומה ביזנטית, 'רחוב הפסלים' ובית המרחץ."},{name:"בית שאן",type:"city",what:"בירת פלאיסטינה סקונדה: רחובות העמודים בצורתם הביזנטית, עד רעש 749."}]])},54286,e=>{"use strict";e.s(["ROMAN_EMPERORS",0,[{name:"אוגוסטוס",latin:"AVGVSTVS",reign:"27 לפנה״ס–14 לספירה",note:"הקיסר הראשון. אישר את הורדוס, חילק את ממלכתו והדיח את ארכלאוס (6 לספירה). לכבודו — קיסריה, סבסטיה והמקדש בפניאס."},{name:"טיבריוס",latin:"TIBERIVS",reign:"14–37",note:"על שמו טבריה. בימיו כיהן פילטוס, ונצלב ישוע. כתובת פילטוס מקיסריה מזכירה מבנה לכבודו."},{name:"קליגולה",latin:"GAIVS",reign:"37–41",note:"ציווה להציב את פסלו בהיכל; נרצח לפני שההוראה בוצעה. ידידו של אגריפס הראשון."},{name:"נירון",latin:"NERO",reign:"54–68",note:"בימיו פרץ המרד הגדול (66), והוא שלח את אספסיאנוס לדכא אותו."},{name:"אספסיאנוס",latin:"VESPASIANVS",reign:"69–79",note:"כבש את הגליל, הוכרז קיסר ב־69 וייסד את השושלת הפלבית. טבע 'יהודה השבויה', ייסד את נאפוליס."},{name:"טיטוס",latin:"TITVS",reign:"79–81",note:"החריב את ירושלים והמקדש (70) כמצביא. שער טיטוס ברומא הוקם אחרי מותו."},{name:"טריאנוס",latin:"TRAIANVS",reign:"98–117",note:"סיפח את הנבטים (106), סלל את הדרך החדשה מבוצרה לים סוף, ודיכא את מרד התפוצות (115–117)."},{name:"אדריאנוס",latin:"HADRIANVS",reign:"117–138",note:"ביקר בארץ (130), ייסד את איליה קפיטולינה, אסר מילה, דיכא את מרד בר כוכבא וקרא לפרובינציה 'סוריה פלשתינה'."},{name:"אנטונינוס פיוס",latin:"ANTONINVS PIVS",reign:"138–161",note:"הקל בגזרות והתיר שוב את המילה ליהודים — הרקע לכינוס אושא."},{name:"ספטימיוס סוורוס",latin:"SEPTIMIVS SEVERVS",reign:"193–211",note:"העניק מעמד עיר לבית גוברין (אלאותרופוליס) וללוד (דיוספוליס). ימי רבי יהודה הנשיא."},{name:"קרקלה",latin:"CARACALLA",reign:"211–217",note:"העניק אזרחות לכל בני החורין (212). מועמד לזיהוי 'אנטונינוס' ידידו של רבי."},{name:"דיוקלטיאנוס",latin:"DIOCLETIANVS",reign:"284–305",note:"טטררכיה, לימס, מחזורי מס (אינדיקציו), העברת הלגיון העשירי לאילה, והרדיפה הגדולה של הנוצרים."},{name:"קונסטנטינוס",latin:"CONSTANTINVS",reign:"306–337",note:"גשר מולוויאן (312), צו מילאנו (313), איחוד האימפריה (324) וייסוד קונסטנטינופוליס (330)."}],"ROMAN_ERAS",0,[{id:"pompey",title:"רומא מגיעה",range:"63–37 לפנה״ס",latin:"RES PUBLICA",note:"פומפיוס, קיסר ומלחמות האזרחים ברומא; בית חשמונאי מאבד את כוחו והורדוס עולה."},{id:"client",title:"מלך חסות ונציבים",range:"37 לפנה״ס – 66 לספירה",latin:"AUGUSTUS",note:"הורדוס ובניו, ואחריהם שלטון רומי ישיר. פירוט מלא בציר בית שני."},{id:"flavian",title:"המרד והשושלת הפלבית",range:"66–96 לספירה",latin:"IUDAEA CAPTA",note:"המרד הגדול, החורבן, ויבנה. רומא מנציחה את ניצחונה במטבעות ובשער טיטוס."},{id:"hadrian",title:"מטריאנוס עד בר כוכבא",range:"98–138 לספירה",latin:"AELIA CAPITOLINA",note:"סיפוח הנבטים, מרד התפוצות, ביקור אדריאנוס, איליה קפיטולינה ומרד בר כוכבא."},{id:"mishnah",title:"שלום רומי ותקופת המשנה",range:"138–235 לספירה",latin:"PAX ROMANA",note:"הגזרות מוקלות, הסנהדרין בגליל, חתימת המשנה ופריחת הערים בימי בית סוורוס."},{id:"crisis",title:"משבר ורפורמה",range:"235–305 לספירה",latin:"TETRARCHIA",note:"אנרכיה ואינפלציה, ואחריהן דיוקלטיאנוס: ארבעה קיסרים, לימס ורדיפת הנוצרים."},{id:"constantine",title:"אל הנצרות",range:"306–324 לספירה",latin:"IN HOC SIGNO",note:"קונסטנטינוס, גשר מולוויאן וצו מילאנו. ב־324 מתחילה התקופה הביזנטית."}],"ROMAN_EVENTS",0,[{id:"RO-001",era:"pompey",year:-63,date:"63 לפנה״ס",title:"פומפיוס כובש את ירושלים",kind:"war",key:!0,summary:"מלחמת האחים החשמונאית מזמינה את רומא; המלוכה מבוטלת.",body:"הורקנוס השני ואריסטובולוס השני ביקשו מפומפיוס להכריע ביניהם. פומפיוס פסק לטובת הורקנוס, צר על הר הבית שבו התבצרו תומכי אריסטובולוס, וכבש אותו. הוא נכנס לקודש הקודשים, ביטל את תואר המלך והפך את הורקנוס ל'אתנרך' — ראש העם. ערי החוף והערים ההלניסטיות נותקו מיהודה.",tip:"63 לפנה״ס היא תחילת התקופה הרומית המוקדמת בארץ וסוף העצמאות החשמונאית. התואר 'אתנרך' — לא מלך.",sites:"הר הבית בירושלים"},{id:"RO-002",era:"pompey",year:-57,date:"57 לפנה״ס",title:"גביניוס מחלק את יהודה לחמישה מחוזות",kind:"rule",summary:"מושל סוריה מפרק את השלטון המרכזי ובונה מחדש את הערים ההלניסטיות.",body:"אולוס גביניוס חילק את יהודה לחמש 'סינהדריות' (מועצות) — ירושלים, גזר, עמתו, יריחו וציפורי — כדי לפורר את כוחם של בני בית חשמונאי. במקביל שיקם ערים שהחשמונאים הרסו, כמו שומרון, בית שאן ודור.",tip:"מכאן ואילך הערים ההלניסטיות (בית שאן, סוסיתא, גדרה) הן ערים עצמאיות־למחצה — בסיס ל'דקאפוליס'.",sites:"ציפורי, יריחו, בית שאן, שומרון"},{id:"RO-003",era:"pompey",year:-47,date:"47 לפנה״ס",title:"יוליוס קיסר מעניק זכויות ליהודים",kind:"rule",summary:"אנטיפטרוס האדומי עולה; בנו הורדוס מתמנה למושל הגליל.",body:"לאחר שהורקנוס ואנטיפטרוס סייעו לקיסר במצרים, הוא העניק ליהודים זכויות: פטור מגיוס, היתר לבנות מחדש את חומות ירושלים ואישור הורקנוס ככהן גדול. אנטיפטרוס מונה לאפיטרופוס, ומינה את בנו פצאל לירושלים ואת הורדוס לגליל. קיסר נרצח ב־44 לפנה״ס.",tip:"משפחת אנטיפטרוס האדומית — מן האדומים שגוירו בימי יוחנן הורקנוס — הופכת לבעלת הכוח האמיתית.",sites:"הגליל"},{id:"RO-004",era:"pompey",year:-40,date:"40 לפנה״ס",title:"פלישת הפרתים; הסנאט ממליך את הורדוס",kind:"war",key:!0,summary:"אנטיגונוס, אחרון מלכי בית חשמונאי, עולה בעזרת הפרתים; הורדוס בורח לרומא.",body:"הפרתים פלשו לסוריה ולארץ והמליכו את מתתיהו אנטיגונוס, בן אריסטובולוס השני. פצאל נשבה ומת, והורקנוס נלקח לבבל. הורדוס נמלט — דרך מצדה, שם השאיר את משפחתו — לרומא, והסנאט הכריז עליו כמלך יהודה.",tip:"הורדוס מונה למלך ב־40 אך שלט בפועל רק מ־37. אנטיגונוס הוא המלך החשמונאי האחרון — לא הורקנוס.",sites:"מצדה"},{id:"RO-005",era:"pompey",year:-37,date:"37 לפנה״ס",title:"הורדוס כובש את ירושלים",kind:"war",key:!0,summary:"בסיוע הלגיונות של סוסיוס; אנטיגונוס מוצא להורג.",body:"אחרי שלוש שנות לחימה כבש הורדוס את ירושלים עם המצביא הרומי סוסיוס. אנטיגונוס הוצא להורג באנטיוכיה בפקודת מרקוס אנטוניוס. כדי לזכות בלגיטימיות נשא הורדוס את מרים החשמונאית — ואחר כך חיסל את בני משפחתה ואותה עצמה.",tip:"מכאן הורדוס הוא 'מלך חסות': עצמאי בענייני פנים, תלוי ברומא במדיניות חוץ ובצבא."},{id:"RO-006",era:"client",year:-31,date:"31 לפנה״ס",title:"קרב אקטיום ורעידת האדמה",kind:"rule",summary:"אוקטביאנוס מנצח את אנטוניוס וקלאופטרה; הורדוס עובר צד ושורד.",body:"הורדוס, שהיה בן חסותו של אנטוניוס, נסע לרודוס והצהיר נאמנות לאוקטביאנוס, שאישר את מלכותו והרחיב אותה. באותה שנה פקדה את הארץ רעידת אדמה קשה, שפגעה גם בקומראן.",tip:"על שם אנטוניוס נקראה מצודת אנטוניה — היא נבנתה לפני אקטיום. אחרי אקטיום הורדוס מקדיש את מפעליו לאוגוסטוס."},{id:"RO-007",era:"client",year:-27,date:"27 לפנה״ס",title:"אוגוסטוס; שומרון נבנית מחדש כסבסטיה",kind:"build",key:!0,summary:"אוקטביאנוס נעשה 'אוגוסטוס' — הקיסר הראשון. הורדוס קורא לשומרון 'סבסטיה'.",body:"סבסטוס הוא אוגוסטוס ביוונית. הורדוס יישב בעיר את חייליו הוותיקים והקים בה מקדש לאוגוסטוס על ראש התל, מעל שרידי ארמון מלכי ישראל. בתקופה הרומית המאוחרת נבנו בה תיאטרון, פורום ורחוב עמודים.",tip:"פולחן הקיסר מתחיל באוגוסטוס. הורדוס בנה לו שלושה מקדשים בארץ: סבסטיה, קיסריה ופניאס (בניאס).",sites:"סבסטיה (שומרון)"},{id:"RO-008",era:"client",year:-20,date:"20 לפנה״ס",title:"מקדש לאוגוסטוס בפניאס",kind:"build",summary:"הורדוס בונה מקדש לקיסר ליד מערת פאן, במעיינות הירדן.",body:"פניאס — על שם האל פאן — הייתה מקום פולחן עוד מן התקופה ההלניסטית (שם נערך קרב פניון, 200 לפנה״ס). הורדוס הקים לפני המערה מקדש לאוגוסטוס. בנו פיליפוס הפך את המקום לבירתו וקרא לו 'קיסריה של פיליפוס'.",tip:"בבניאס רואים את חזית מערת פאן, הגומחות לפסלים ושרידי המקדשים. בברית החדשה — 'קיסריה של פיליפוס', מקום הודאת פטרוס.",sites:"בניאס (שמורת נחל חרמון)"},{id:"RO-009",era:"client",year:-10,date:"22–10 לפנה״ס",title:"קיסריה ונמל סבסטוס",kind:"build",key:!0,summary:"עיר נמל רומית על חוף בלי מפרץ טבעי, בבטון שהתקשה במים.",body:"הורדוס בנה את קיסריה במקום מגדל סטרטון, עם נמל מלאכותי עצום, מקדש לאוגוסטוס ולרומא, ארמון על לשון סלע, תיאטרון והיפודרום (היפוסטדיום). העיר נחנכה ב־10/9 לפנה״ס, ואחרי 6 לספירה הייתה בירת הפרובינציה.",tip:"קיסריה היא עיר ההדגמה הטובה ביותר בארץ לאדריכלות רומית: מקדש פודיום, תיאטרון, היפודרום, אמות מים.",sites:"גן לאומי קיסריה, חוף האקוודוקט"},{id:"RO-010",era:"client",year:-4,date:"4 לפנה״ס",title:"מות הורדוס ומרד וארוס",kind:"war",key:!0,summary:"מהומות בכל הארץ, טבח בידי מושל סוריה, וחלוקת הממלכה בין שלושה בנים.",body:"הורדוס מת ביריחו ונקבר בהרודיון. מרידות פרצו ביהודה, בגליל ובעבר הירדן; ורוס, מושל סוריה, דיכא אותן בטבח ('פולמוס של ורוס') והחריב את ציפורי. אוגוסטוס חילק את הממלכה: ארכלאוס — אתנרך יהודה, שומרון ואדום; אנטיפס — טטררך הגליל ועבר הירדן; פיליפוס — טטררך הגולן והבשן.",tip:"שלושה בנים, שני תארים: אתנרך (ארכלאוס) וטטררך (אנטיפס ופיליפוס). אף אחד מהם אינו 'מלך'.",sites:"הרודיון, ציפורי",concept:!0},{id:"RO-011",era:"client",year:6,date:"6 לספירה",title:"יהודה הופכת לפרובינציה של נציבים",kind:"rule",key:!0,concept:!0,summary:"ארכלאוס מודח; נציב רומי יושב בקיסריה, ומפקד קויריניוס מעורר התנגדות.",body:"אוגוסטוס הדיח את ארכלאוס והעמיד בראש יהודה נציב (פרפקט) כפוף למושל סוריה. המפקד לצורכי מס שערך קויריניוס עורר את יהודה הגלילי להקים את 'הפילוסופיה הרביעית' — שורש הקנאים.",tip:"תקופת הנציבים הראשונה: 6–41 לספירה. מושב הנציב — קיסריה; לירושלים עלה בחגים.",sites:"קיסריה"},{id:"RO-012",era:"client",year:19,date:"סביב 19 לספירה",title:"אנטיפס מייסד את טבריה",kind:"build",summary:"בירה חדשה לגליל, על שם הקיסר טיבריוס — ובנויה על קברים.",body:"הורדוס אנטיפס העביר את בירתו מציפורי לטבריה. משום שנבנתה על בית קברות, נחשבה בעיני יהודים רבים לטמאה, ואנטיפס יישב בה תושבים בכפייה. רק בדורות שאחרי מרד בר כוכבא היא נעשתה עיר יהודית מרכזית.",tip:"טבריה תהיה התחנה האחרונה בנדודי הסנהדרין ומקום חתימת התלמוד הירושלמי.",sites:"טבריה, חמת טבריה"},{id:"RO-013",era:"client",year:30,date:"26–36 לספירה",title:"פונטיוס פילטוס",kind:"rule",key:!0,concept:!0,summary:"הנציב שבימיו נצלב ישוע; שמו נמצא על כתובת בקיסריה.",body:"פילטוס התעמת עם היהודים בגלל הכנסת סמלי צבא לירושלים ושימוש בכספי המקדש לאמת מים. בימיו, בסביבות 30 לספירה, נצלב ישוע. ב־1961 נמצאה בתיאטרון קיסריה כתובת המזכירה מבנה שהקדיש לטיבריוס. מטבעותיו נמצאו מתחת לריצוף רחוב המדרגות בעיר דוד.",tip:"הכתובת מקיסריה היא העדות הארכיאולוגית היחידה לשמו. ההעתק נמצא בתיאטרון, המקור במוזיאון ישראל.",sites:"קיסריה, עיר דוד"},{id:"RO-014",era:"client",year:40,date:"40 לספירה",title:"קליגולה מצווה להציב את פסלו במקדש",kind:"rule",summary:"המשבר החמור ביותר לפני המרד — נמנע ברגע האחרון.",body:"הקיסר גאיוס קליגולה הורה למושל סוריה, פטרוניוס, להציב את פסלו בהיכל. יהודים רבים הפגינו מול פטרוניוס, והוא עיכב את הביצוע. קליגולה נרצח בתחילת 41, והפסל לא הוצב מעולם. באותו זמן הגיע פילון האלכסנדרוני ברומא בראש משלחת יהודי אלכסנדריה.",tip:"אם שואלים על 'גורם מיידי למרד הגדול' — פסל קליגולה אינו התשובה: המשבר הסתיים ב־41."},{id:"RO-015",era:"client",year:41,date:"41–44 לספירה",title:"אגריפס הראשון — מלך על כל הארץ",kind:"rule",concept:!0,summary:"נכד הורדוס מאחד לזמן קצר את הממלכה ומתחיל את החומה השלישית.",body:"אגריפס, ידידם של קליגולה וקלאודיוס, קיבל את כל שטחי סבו. הוא נהג ביהודים באהדה והחל לבנות את 'החומה השלישית' בצפון ירושלים, עד שרומא עצרה אותו. מת בקיסריה ב־44, ואחריו חזר שלטון הנציבים.",tip:"יש השערה שיד אבשלום בנחל קדרון היא קברו של אגריפס הראשון."},{id:"RO-016",era:"flavian",year:66,date:"66 לספירה",title:"פרוץ המרד הגדול",kind:"war",key:!0,concept:!0,summary:"שוד כספי המקדש, הפסקת הקורבן לשלום הקיסר ומפלת קסטיוס גאלוס.",body:"המתח בקיסריה בין יהודים לנכרים, שחיתות הנציב גסיוס פלורוס ושוד אוצר המקדש הציתו את המרד. הכהנים הפסיקו את הקורבן לשלום הקיסר. מושל סוריה, קסטיוס גאלוס, צר על ירושלים, נסוג והובס במעלה בית חורון.",tip:"בניגוד למרד בר כוכבא, המרד הגדול פרץ באופן ספונטני ולא תוכנן מראש.",sites:"מעלה בית חורון"},{id:"RO-017",era:"flavian",year:67,date:"67 לספירה",title:"אספסיאנוס כובש את הגליל",kind:"war",key:!0,concept:!0,summary:"יודפת, גמלא ומגדל נלחמות ונופלות; ציפורי נכנעת.",body:"נירון שלח את אספסיאנוס עם שלושה לגיונות. יודפת נפלה אחרי 47 ימי מצור, ומפקד הגליל, יוסף בן מתתיהו, נכנע וניבא לאספסיאנוס שיהיה קיסר. גמלא נפלה בסתיו, ובכנרת נערך קרב סירות ליד מגדל (טריכאי). ציפורי פתחה שעריה לרומאים.",tip:"בגמלא רואים את הפרצה בחומה, ראשי חצים ואבני בליסטראות, ובית כנסת מימי בית שני.",sites:"יודפת, גמלא, מגדלא"},{id:"RO-018",era:"flavian",year:69,date:"69 לספירה",title:"שנת ארבעת הקיסרים",kind:"rule",summary:"נירון מת, שלושה קיסרים נופלים, ואספסיאנוס מוכרז קיסר.",body:"אחרי מות נירון (68) התחלפו גלבה, אותו וויטליוס. ביולי 69 הכריזו הלגיונות במזרח על אספסיאנוס כקיסר. הוא יצא לרומא והשאיר את המלחמה ביהודה לבנו טיטוס. כך נוסדה השושלת הפלבית (69–96).",tip:"הנבואה של יוסף בן מתתיהו התגשמה — ובזכותה הוא חי ברומא בחסות הפלבים וכתב שם את ספריו."},{id:"RO-019",era:"flavian",year:70,date:"70 לספירה",title:"חורבן ירושלים והמקדש",kind:"war",key:!0,concept:!0,summary:"מצור של חמישה חודשים; המקדש נשרף בט' באב.",body:"טיטוס פרץ את החומה השלישית ואחר כך את השנייה, כבש את האנטוניה (י\"ז בתמוז — הפסקת התמיד), והמקדש נשרף בט' באב. העיר העליונה נפלה בח' באלול. טיטוס השאיר את מגדלי הורדוס עומדים, והלגיון העשירי חנה על חורבות העיר.",tip:"בכותל הדרומי רואים את אבני המפולת מקשת רובינסון על הרחוב ההרודיאני; בבית השרוף — שכבת האפר של 70.",sites:"הר הבית, הבית השרוף, קשת רובינסון"},{id:"RO-020",era:"flavian",year:70,date:"70 לספירה",title:"יבנה וחכמיה",kind:"jewish",key:!0,concept:!0,summary:"רבן יוחנן בן זכאי בונה מחדש את ההנהגה, בלי מקדש.",body:"לפי המסורת נמלט רבן יוחנן בן זכאי מירושלים הנצורה, הגיע אל אספסיאנוס וביקש 'תן לי יבנה וחכמיה'. ביבנה התכנסו החכמים, ותקנות יבנה העבירו מנהגי מקדש לכל מקום — נטילת לולב שבעה ימים, תקיעת שופר בשבת ביבנה — וקבעו תפילות במקום הקורבנות.",tip:"המרצה הדגיש: לא הייתה גלות המונית ב־70. הירידה הדמוגרפית נבעה בעיקר מן ההרג במלחמה.",sites:"יבנה"},{id:"RO-021",era:"flavian",year:71,date:"71 לספירה ואילך",title:"יהודה השבויה ושער טיטוס",kind:"rule",concept:!0,summary:"תהלוכת ניצחון ברומא, מטבעות 'יהודה השבויה' ומס לקפיטול.",body:"אספסיאנוס וטיטוס ערכו תהלוכת ניצחון שבה הוצגו כלי המקדש. נטבעו מטבעות IUDAEA CAPTA: עץ תמר ודמות אישה אבלה. מס מחצית השקל הוסב ל'מס היהודים' (fiscus Iudaicus) לטובת מקדש יופיטר ברומא. שער טיטוס, ועליו תבליט המנורה, הוקם אחרי מות טיטוס (81).",tip:"התבליט בשער טיטוס הוא התיאור העתיק המוכר של מנורת המקדש — המקור לסמל המדינה."},{id:"RO-022",era:"flavian",year:72,date:"72 לספירה",title:"נאפוליס נוסדת ליד שכם",kind:"build",summary:"עיר רומית חדשה — 'פלביה נאפוליס' — שממנה השם שכם־נבלוס.",body:"אספסיאנוס ייסד עיר חדשה בין עיבל לגריזים, מערבית לשכם הקדומה. השם נאפוליס ('עיר חדשה') השתמר בשם הערבי נבלוס. העיר נעשתה מרכז השומרונים, ולמרגלות הר גריזים נבנה מאוחר יותר מקדש לזאוס.",tip:"השם הרומי השתמר בשם הערבי נבלוס. לעומת זאת בבית ג'וברין שרד דווקא השם השמי, ולא השם הרומי אלאותרופוליס.",sites:"שכם, הר גריזים"},{id:"RO-023",era:"flavian",year:73,date:"73 (או 74) לספירה",title:"נפילת מצדה",kind:"war",key:!0,concept:!0,summary:"אחרי הרודיון ומכוור — המבצר האחרון של המורדים.",body:"לוקיליוס בסוס כבש את הרודיון ומכוור; פלביוס סילבה צר על מצדה עם הלגיון העשירי, בנה חומת מצור, מחנות וסוללה. לפי יוסף בן מתתיהו, המגינים — סיקריים בפיקוד אלעזר בן יאיר — בחרו למות.",tip:"במצדה רואים את מחנות הצבא, חומת המצור והסוללה מן המערב, וגם את ארמונות הורדוס, בית הכנסת והמקוואות.",sites:"מצדה, מכוור (בירדן), הרודיון"},{id:"RO-024",era:"flavian",year:75,date:"אחרי 70 לספירה",title:"קיסריה — קולוניה ובירה; הלגיון העשירי בירושלים",kind:"rule",concept:!0,summary:"יהודה פרובינציה נפרדת; מושלה יושב בקיסריה, והצבא חונה בירושלים.",body:"אחרי החורבן נעשתה יהודה פרובינציה בדרגת פרייטור, ובראשה מושל שגם פיקד על הלגיון. אספסיאנוס העניק לקיסריה מעמד של קולוניה רומית. הלגיון העשירי פרטנסיס חנה בירושלים, שלא הייתה לה חומה — מפעל הרעפים שלו נמצא בבנייני האומה.",tip:"לבירת הפרובינציה (קיסריה) ולמחנה הלגיון (ירושלים) יש תפקידים שונים — שאלה נפוצה.",sites:"קיסריה, ירושלים (בנייני האומה)"},{id:"RO-025",era:"flavian",year:90,date:"סוף המאה ה־1",title:"רבן גמליאל ביבנה וברכת המינים",kind:"jewish",concept:!0,summary:"הנשיאות מתבססת, ונוסח התפילה מתגבש.",body:"רבן גמליאל דיבנה, נכד רבן גמליאל הזקן, עמד בראש החכמים. בימיו ניסח שמואל הקטן את ברכת המינים — הברכה ה־19 בשמונה עשרה — נגד פורשים, מלשינים ויהודים־נוצרים, ובכך העמיק את הנתק בין היהדות לנצרות.",tip:"בית הנשיאות — צאצאי הלל הזקן — ינהיג את היהודים בארץ עד ביטול הנשיאות במאה ה־5."},{id:"RO-026",era:"hadrian",year:106,date:"106 לספירה",title:"טריאנוס מספח את ממלכת הנבטים",kind:"rule",key:!0,summary:"נוסדת פרובינציה ערביה, ובירתה בוצרה; נסללת הדרך החדשה.",body:"עם מות המלך הנבטי האחרון סיפח טריאנוס את הממלכה. בשנים 111–114 נסללה 'הדרך החדשה של טריאנוס' (ויה טריאנה נובה) מבוצרה לים סוף, ולאורכה אבני מיל. ערי הנגב הנבטיות המשיכו להתקיים — וישגשגו בתקופה הביזנטית.",tip:"עבדת, ממשית, שבטה וחלוצה הן ערי דרך הבשמים — אתר מורשת עולמית.",sites:"עבדת, ממשית, שבטה"},{id:"RO-027",era:"hadrian",year:116,date:"115–117 לספירה",title:"מרד התפוצות — פולמוס של קיטוס",kind:"war",concept:!0,summary:"יהודי מצרים, קירנאיקה, קפריסין ומסופוטמיה מורדים בטריאנוס.",body:"בזמן שטריאנוס נלחם בפרתים פרצו מרידות יהודיות קשות בתפוצות. הגנרל לוסיוס קיטוס דיכא אותן, ובפי חז״ל נקרא האירוע 'פולמוס של קיטוס'. קהילת אלכסנדריה הגדולה כמעט נמחקה.",tip:"המרידות נקראות על שם מדכאיהן: ורוס (4 לפנה״ס), קיטוס (115–117), גאלוס (351)."},{id:"RO-028",era:"hadrian",year:120,date:"סביב 120 לספירה",title:"לגיון שני בפרובינציה — לגיו",kind:"rule",concept:!0,summary:"הפרובינציה משודרגת; לגיון חונה בעמק יזרעאל.",body:"אחרי מרד התפוצות הוצב לגיון נוסף בצפון — תחילה השני טריאנוס ואחר כך השישי פרטה — במחנה ליד תל מגידו. המקום נקרא על שמו 'לגיו' (אל־לג'ון), ובספרות חז״ל כפר עותנאי. מושל הפרובינציה הפך לבעל דרגה קונסולרית.",tip:"בכפר עותנאי, סמוך למחנה, נמצא אולם תפילה נוצרי מן המאה ה־3 עם פסיפס — מהעדויות המוקדמות לנצרות בארץ.",sites:"תל מגידו, צומת מגידו"},{id:"RO-029",era:"hadrian",year:130,date:"129/130 לספירה",title:"ביקור אדריאנוס בארץ",kind:"rule",summary:"הקיסר הנודד מבקר בפרובינציה; שערים ופסלים מוקמים לכבודו.",body:"אדריאנוס סייר במזרח, ובגרש ובתל שלם נבנו לכבודו שערי ניצחון. בתל שלם שבעמק בית שאן נמצא ב־1975 פסל ברונזה של אדריאנוס — מן הפסלים הרומיים השמורים ביותר בעולם. ציפורי קיבלה כנראה בתקופה זו את השם דיוקיסריה.",tip:"הפסל מתל שלם מוצג במוזיאון ישראל. ציפורי = דיוקיסריה; בית שאן = סקיתופוליס.",sites:"תל שלם, ציפורי"},{id:"RO-030",era:"hadrian",year:131,date:"סביב 130 לספירה",title:"איליה קפיטולינה ואיסור המילה",kind:"rule",key:!0,concept:!0,summary:"ירושלים נבנית כעיר אלילית; גזירת המילה מרעה את היחסים.",body:"אדריאנוס החליט לבנות את ירושלים כקולוניה רומית — איליה על שמו, קפיטולינה על שם האלים הקפיטוליניים — עם רחובות עמודים ומקדשים. הוא גם אסר על מילה, כנראה מתוך תפיסה הלניסטית של שלמות הגוף ולא כגזירה נגד היהודים.",tip:"מחלוקת המקורות: דיו קסיוס — העיר קדמה למרד וגרמה לו; אאוזביוס — היא באה כעונש. מטבעות איליה בידי המורדים והקרדו המזרחי תומכים בדיו.",sites:"הקרדו המזרחי, קשת אקה הומו, שער שכם הרומי"},{id:"RO-031",era:"hadrian",year:132,date:"132 לספירה",title:"פרוץ מרד בר כוכבא",kind:"war",key:!0,concept:!0,summary:"מרד מתוכנן, בהנהגת שמעון בר כוסבה ובתמיכת רבי עקיבא.",body:"כשאדריאנוס עזב את האזור פרץ המרד. רבי עקיבא דרש על המנהיג 'דרך כוכב מיעקב'. המורדים טבעו מטבעות 'לחירות ירושלים' ועליהם חזית המקדש, והכינו מראש מערכות מסתור בשפלה, בחבל בנימין ואף בגליל.",tip:"מערכות מסתור אפשר לראות בשפלה (למשל בחורבת מדרס ובמערות חזן). אין עדות שהמורדים כבשו את ירושלים.",sites:"מערכות מסתור בשפלת יהודה"},{id:"RO-032",era:"hadrian",year:134,date:"132–135 לספירה",title:"אגרות בר כוכבא וארכיון בבתא",kind:"war",concept:!0,summary:"מסמכים מקוריים מן המרד, שנמצאו במערות מדבר יהודה.",body:"במערת האגרות בנחל חבר, שחפר יגאל ידין ב־1960–61, נמצאו אגרות של שמעון בר כוסבה אל מפקדיו בעין גדי — ומהן שמו המקורי — וארכיון בבתא, אישה עשירה שלקחה עמה את שטרות נכסיה. מסמכים נוספים נמצאו בוואדי מורבעאת שבנחל דרגה.",tip:"'בר כוכבא' ו'בר כוזיבא' הם שיבושים מאוחרים; באגרות — 'שמעון בר כוסבה'.",sites:"נחל חבר, נחל דרגה (מוזיאון ישראל)"},{id:"RO-033",era:"hadrian",year:135,date:"135 לספירה",title:"נפילת ביתר",kind:"war",key:!0,concept:!0,summary:"המעוז האחרון נופל — לפי המסורת בט' באב.",body:"בר כוכבא התבצר בביתר, ליד הכפר בתיר שדרומית־מערבית לירושלים. לפי דיו קסיוס נחרבו 50 מבצרים ו־985 כפרים. יהודה התרוקנה מיהודים, ומרכז היישוב עבר לגליל.",tip:"חמשת אסונות תשעה באב: המרגלים, חורבן שני הבתים, לכידת ביתר וחרישת העיר.",sites:"חורבת ביתר (ח'רבת אל־יהוד ליד בתיר)"},{id:"RO-034",era:"hadrian",year:136,date:"אחרי 135 לספירה",title:"גזרות השמד וסוריה פלשתינה",kind:"jewish",key:!0,concept:!0,summary:"איסור מצוות, עשרת הרוגי מלכות, ושם חדש לפרובינציה.",body:"אדריאנוס אסר לימוד תורה ברבים, מילה, שבת, הסמכת חכמים ובתי דין. בין עשרת הרוגי מלכות — רבי עקיבא ורבי יהודה בן בבא, שהסמיך חכמים בין אושא לשפרעם. שם הפרובינציה שונה מיהודה ל'סוריה פלשתינה', ויהודים נאסרו מלהיכנס לאיליה (למעט בתשעה באב, במאות הבאות).",tip:"גזרות אדריאנוס אסרו לקיים מצוות; גזרות אנטיוכוס גם כפו לעבור עליהן — הבחנה שהמרצה הדגיש."},{id:"RO-035",era:"mishnah",year:140,date:"אחרי 138 לספירה",title:"אנטונינוס פיוס מקל; כינוס אושא",kind:"jewish",concept:!0,summary:"הגזרות מתבטלות בהדרגה, והחכמים מתכנסים בגליל.",body:"יורשו של אדריאנוס התיר שוב את המילה ליהודים. החכמים התכנסו באושא שבגליל המערבי, ושם התחדשו הסנהדרין והנשיאות בהנהגת רבן שמעון בן גמליאל. נדודי הסנהדרין: יבנה ← אושא ← שפרעם ← בית שערים ← ציפורי ← טבריה.",tip:"הנדודים הם מדרום־מערב לצפון־מזרח — כי מרכז החיים היהודי עבר מיהודה לגליל. לפי המחקר נדד רק הגרעין המצומצם של הסנהדרין."},{id:"RO-036",era:"mishnah",year:200,date:"סביב 200 לספירה",title:"רבי יהודה הנשיא חותם את המשנה",kind:"jewish",key:!0,concept:!0,summary:"בציפורי; שיא יוקרת בית הנשיא. רבי נקבר בבית שערים.",body:"רבי יהודה הנשיא העביר את הסנהדרין מבית שערים לציפורי, ושם ערך את המשנה בשישה סדרים — זרעים, מועד, נשים, נזיקין, קדשים, טהרות. המסורת מספרת על ידידותו עם קיסר בשם 'אנטונינוס' (אולי קרקלה). אחרי מותו נקבר בבית שערים, ויהודים רבים ביקשו להיקבר לידו.",tip:'אין תאריך מדויק: 200 או 220 — שניהם מקובלים. שישה סדרים: זמ"ן נק"ט.',sites:"ציפורי, בית שערים"},{id:"RO-037",era:"mishnah",year:200,date:"200 לספירה",title:"ספטימיוס סוורוס מייסד ערים",kind:"build",key:!0,summary:"בית גוברין נעשית אלאותרופוליס, ולוד — דיוספוליס.",body:"הקיסר ספטימיוס סוורוס (193–211) העניק מעמד של עיר לבית גוברין ('אלאותרופוליס' — עיר בני החורין) וללוד ('דיוספוליס' — עיר זאוס). לערים ניתנו שטחי שיפוט נרחבים. בימי השושלת הסוורית פרחו גם הערים היהודיות, והיחסים עם רומא היו טובים.",tip:"באלאותרופוליס נבנה אמפיתיאטרון מלכתחילה — לא הוסב מהיפודרום כמו בקיסריה ובבית שאן.",sites:"בית גוברין, לוד"},{id:"RO-038",era:"mishnah",year:212,date:"212 לספירה",title:"קרקלה מעניק אזרחות לכולם",kind:"rule",summary:"כל בני החורין באימפריה נעשים אזרחים רומיים.",body:"צו קרקלה (Constitutio Antoniniana) העניק אזרחות רומית לכל תושבי האימפריה החופשיים, ובהם היהודים. במקביל הגדיל את בסיס המס. קרקלה (211–217) הוא אחד המועמדים לזיהוי 'אנטונינוס' ידידו של רבי.",tip:"ידע כללי: אחרי 212 ההבחנה בין אזרח לנתין מאבדת מחשיבותה."},{id:"RO-039",era:"mishnah",year:221,date:"221 לספירה",title:"אמאוס נעשית ניקופוליס",kind:"build",summary:"עיר הניצחון — באזור לטרון.",body:"הקיסר אלגבלוס העניק לאמאוס מעמד של עיר בשם ניקופוליס, לבקשת יוליוס אפריקנוס. אמאוס — מן 'חמת', מים חמים — הייתה מקום קרב יהודה המכבי (165 לפנה״ס), ובמסורת הנוצרית מזוהה עם הופעת ישוע לאחר התחייה.",tip:"בפארק קנדה ובאמאוס־ניקופוליס יש שרידי כנסיות ביזנטיות ומרחץ רומי.",sites:"אמאוס־ניקופוליס (לטרון)"},{id:"RO-040",era:"mishnah",year:232,date:"סביב 232 לספירה",title:"אוריגנס מגיע לקיסריה",kind:"christian",concept:!0,summary:"הוגה הדעות הנוצרי מקים בקיסריה מרכז לימוד וספרייה.",body:"אוריגנס עבר מאלכסנדריה לקיסריה, ושם כתב ולימד. הספרייה שהקים תשמש את אאוזביוס, בישוף קיסריה, במאה הבאה. קיסריה נעשתה מרכז אינטלקטואלי נוצרי — וגם מקום מושבם של חכמים יהודים.",tip:"אוריגנס (מאה 3) ואאוזביוס (מאה 4) — שניהם קיסריה. אל תחליפו ביניהם.",sites:"קיסריה"},{id:"RO-041",era:"crisis",year:235,date:"235–284 לספירה",title:"משבר המאה השלישית",kind:"rule",concept:!0,summary:"אנרכיה, פלישות ברברים, אינפלציה ומיסים כבדים.",body:"קיסרים מונו ונרצחו בזה אחר זה; לעיתים רומא אף שילמה לברברים שלא יתקפו. הכסף איבד את ערכו, והמיסים הכבידו. בארץ זה עודד הגירה — אחד הגורמים להתמעטות האוכלוסייה היהודית.",tip:"המשבר מסביר את עליית דיוקלטיאנוס ואת הרפורמות שלו."},{id:"RO-042",era:"crisis",year:250,date:"אמצע המאה ה־3",title:"טבריה — מרכז היהדות בארץ",kind:"jewish",summary:"הנשיאות והישיבה הגדולה מתבססות בטבריה.",body:"בימי רבי יוחנן בר נפחא וריש לקיש נעשתה טבריה לעיר היהודית החשובה, ושם יתגבש התלמוד הירושלמי. בטבריה נחשף מבנה בסיליקה גדול שהחופר יזהר הירשפלד הציע לזהותו כמבנה הסנהדרין — השערה שנויה במחלוקת.",tip:"טבריה היא התחנה האחרונה בנדודי הסנהדרין. בחמת טבריה — בית הכנסת עם גלגל המזלות המוקדם בארץ.",sites:"טבריה, חמת טבריה"},{id:"RO-043",era:"crisis",year:271,date:"270–272 לספירה",title:"זנוביה מתדמור שולטת במזרח",kind:"war",summary:"ממלכת תדמור משתלטת לזמן קצר על הארץ ומצרים.",body:"המלכה זנוביה מתדמור (פלמירה) ניצלה את חולשת רומא והשתלטה על סוריה, ארץ ישראל ומצרים. הקיסר אורליאנוס הביס אותה ב־272. האפיזודה ממחישה את עומק משבר המאה השלישית.",tip:"ידע כללי בלבד — לא נמצא ברשימת המושגים."},{id:"RO-044",era:"crisis",year:290,date:"284–305 לספירה",title:"דיוקלטיאנוס: טטררכיה ולימס",kind:"rule",key:!0,concept:!0,summary:"ארבעה קיסרים, מבצרי גבול, והלגיון העשירי עובר לאילה.",body:"דיוקלטיאנוס חילק את השלטון לשני 'אוגוסטים' ושני 'קיסרים', ארגן מחדש את המיסוי במחזורי 'אינדיקציו' וביצר את גבול המדבר — הלימס הפלסטיני — במצודות כמו יטבתה ועין בוקק. הלגיון העשירי הועבר מירושלים לאילה. סביב 300 נבנתה סביב ירושלים חומה חדשה.",tip:"במצודת יטבתה נמצאה כתובת הקדשה של הטטררכים. אילה = אזור אילת ועקבה.",sites:"יטבתה, עין בוקק, אילת"},{id:"RO-045",era:"crisis",year:303,date:"303–311 לספירה",title:"הרדיפה הגדולה של הנוצרים",kind:"christian",summary:"הרדיפה האחרונה והקשה; קדושים מעונים גם בקיסריה.",body:"דיוקלטיאנוס ושותפיו הורו להרוס כנסיות, לשרוף ספרים ולהוציא להורג מי שסירב להקריב לאלים. אאוזביוס תיעד את המעונים בארץ בחיבורו 'על מעוני ארץ ישראל'. הרדיפה הסתיימה בצו הסובלנות של גלריוס (311).",tip:"מכאן הניגוד הדרמטי: בתוך עשור הנצרות הופכת מדת נרדפת לדת מועדפת."},{id:"RO-046",era:"constantine",year:312,date:"312 לספירה",title:"הקרב בגשר מולוויאן",kind:"christian",key:!0,concept:!0,summary:"קונסטנטינוס מנצח את מקסנטיוס אחרי חזון הכריסטוגרם.",body:"לפני הקרב, על נהר הטיבר ברומא, ראה קונסטנטינוס את צירוף האותיות היווניות חי ורו (ראשי התיבות של 'כריסטוס') ושמע 'בסימן זה תנצח'. הניצחון שכנע אותו בכוחה של הנצרות, אבל הוא הוטבל רק על ערש דווי ב־337.",tip:"IN HOC SIGNO VINCES — 'בסימן זה תנצח'."},{id:"RO-047",era:"constantine",year:313,date:"313 לספירה",title:"צו מילאנו",kind:"christian",key:!0,concept:!0,summary:"הנצרות מוכרת כדת מותרת.",body:"קונסטנטינוס וליקיניוס, קיסר המזרח, הכריזו על חופש פולחן ועל השבת רכוש הכנסייה. הנצרות נעשתה 'דת מותרת' (Religio Licita) — עדיין לא דת המדינה.",tip:"מותרת ב־313; מועדפת אחרי 324; דת המדינה היחידה — רק ב־380, בימי תאודוסיוס הראשון."},{id:"RO-048",era:"constantine",year:324,date:"324 לספירה",title:"קונסטנטינוס מאחד את האימפריה",kind:"rule",key:!0,summary:"ניצחון על ליקיניוס; ארץ ישראל עוברת לשלטון נוצרי — התקופה הביזנטית מתחילה.",body:"עם השתלטותו על המזרח נעשה קונסטנטינוס לקיסר יחיד. אין כאן כיבוש: אותה אימפריה ואותם קיסרים, אבל הדת והתרבות משתנות — מאימפריה פגאנית לנוצרית. המשך הסיפור בציר התקופה הביזנטית.",tip:"324 היא שנת הפתיחה של התקופה הביזנטית בארץ בחלוקה של הקורס (324–638)."}],"ROMAN_KINDS",0,[{id:"war",title:"מלחמות ומרידות"},{id:"rule",title:"שלטון ומנהל"},{id:"jewish",title:"יהדות וחכמים"},{id:"build",title:"ערים ובנייה"},{id:"christian",title:"נצרות"}],"ROMAN_LEGIONS",0,[{name:"הלגיון העשירי",latin:"LEGIO X FRETENSIS",note:"השתתף בדיכוי המרד הגדול ובמצור על מצדה; חנה בירושלים מ־70 ועד שדיוקלטיאנוס העבירו לאילה. סמליו: חזיר הבר, ספינה ונפטון."},{name:"הלגיון השישי",latin:"LEGIO VI FERRATA",note:"'המשוריין'. חנה ליד תל מגידו, במקום שנקרא על שמו לגיו (כפר עותנאי)."},{name:"הלגיון השני",latin:"LEGIO II TRAIANA",note:"הוצב בצפון הארץ אחרי מרד התפוצות, לפני השישי."}],"ROMAN_SITES",0,[{name:"קיסריה",latin:"CAESAREA",region:"מישור החוף",what:"עירו של הורדוס ובירת הפרובינציה: נמל סבסטוס, מקדש אוגוסטוס ורומא, תיאטרון, היפודרום, אמות מים וכתובת פילטוס."},{name:"סבסטיה",latin:"SEBASTE",region:"שומרון",what:"שומרון המקראית שהורדוס בנה מחדש לכבוד אוגוסטוס: מקדש, תיאטרון, רחוב עמודים ופורום."},{name:"בניאס",latin:"PANEAS",region:"צפון",what:"מערת פאן והגומחות, מקדש אוגוסטוס של הורדוס, וקיסריה של פיליפוס."},{name:"הרודיון",latin:"HERODIUM",region:"מדבר יהודה",what:"ארמון־מבצר, תיאטרון עם פרסקאות וקבר הורדוס; גם מוקד במרד בר כוכבא."},{name:"מצדה",latin:"MASADA",region:"ים המלח",what:"ארמונות הורדוס, ומעליהם מערך המצור הרומי השלם ביותר בעולם: מחנות, חומה וסוללה."},{name:"גמלא ויודפת",region:"גולן וגליל",what:"ערים שנלחמו ונחרבו ב־67: פרצות בחומה, ראשי חצים ואבני בליסטראות."},{name:"טבריה",latin:"TIBERIAS",region:"כנרת",what:"בירת אנטיפס ובהמשך מרכז היהדות: הסנהדרין, הישיבה והתלמוד הירושלמי."},{name:"ציפורי",latin:"DIOCAESAREA",region:"הגליל התחתון",what:"בירת הגליל, מקום חתימת המשנה: תיאטרון, בתים עם פסיפסים ('המונה ליזה של הגליל') ובית כנסת."},{name:"בית שערים",region:"עמק יזרעאל",what:"קטקומבות וסרקופגים — ובהם כנראה קבר רבי יהודה הנשיא. אתר מורשת עולמית."},{name:"בית שאן",latin:"SCYTHOPOLIS",region:"עמק בית שאן",what:"עיר הדקאפוליס: רחוב פלדיוס, תיאטרון, מרחצאות, לטרינות ואמפיתיאטרון."},{name:"בית גוברין",latin:"ELEUTHEROPOLIS",region:"השפלה",what:"עיר סוורוס: אמפיתיאטרון שנבנה ככזה מלכתחילה, ובסביבה מערכות מסתור ומערות פעמון."},{name:"תל שלם",region:"עמק בית שאן",what:"מחנה צבאי ושער לכבוד אדריאנוס; כאן נמצא פסל הברונזה של הקיסר."},{name:"נחל חבר ונחל דרגה",region:"מדבר יהודה",what:"מערות המסמכים של מרד בר כוכבא: אגרות בר כוסבה וארכיון בבתא."},{name:"ירושלים — איליה קפיטולינה",latin:"AELIA CAPITOLINA",region:"ירושלים",what:"השער הרומי מתחת לשער שכם, קשת אקה הומו, הקרדו המזרחי ועמודי מיל ומחנה הלגיון."},{name:"לגיו",latin:"LEGIO",region:"עמק יזרעאל",what:"מחנה הלגיון השישי ליד תל מגידו; בכפר עותנאי הסמוך — אולם תפילה נוצרי מן המאה ה־3."},{name:"יטבתה ועין בוקק",region:"הערבה וים המלח",what:"מצודות הלימס מימי דיוקלטיאנוס; ביטבתה — כתובת הטטררכים."}]])},43219,e=>{"use strict";e.s(["default",0,[{id:"egypt-canaan",title:"מצרים, כנען וראשית ישראל",subtitle:"מקרב מגידו ועד ראשית תקופת הברזל",events:[{id:"megiddo",title:"תחותמס השלישי וקרב מגידו",reference:"בערך 1457 לפנה״ס",body:"פרעה תחותמס השלישי מביס קואליציה של שליטי ערים כנעניות ליד מגידו. זהו שלב מרכזי בביסוס ההגמוניה המצרית בכנען.",takeaway:"כיבוש וביסוס שליטה מצרית.",kind:"egypt",disputed:!1,sections:[]},{id:"amenhotep",title:"אמנחותפ השלישי",reference:"בערך 1390–1350 לפנה״ס",body:"מצרים מנהלת אימפריה אזורית. חלק מן ההתכתבות שנמצאה אחר כך באל־עמארנה קשור לסוף תקופתו.",kind:"egypt",disputed:!1,sections:[]},{id:"amarna",title:"אחנתון ומכתבי אל־עמארנה",reference:"בערך 1350 לפנה״ס",body:"בארכיון בבירת אחנתון נשמרו מכתבים של שליטי ערי־מדינה בכנען, ובהן מגידו וירושלים, אל פרעה. הם מבקשים עזרה, מצהירים נאמנות ומדווחים על סכסוכים.",takeaway:"לא כיבוש חדש — ניהול שוטף של שליטה מצרית דרך שליטים מקומיים.",kind:"egypt",disputed:!1,sections:[]},{id:"ramses",title:"רעמסס השני",reference:"1279–1213 לפנה״ס",body:"פרעה מהשושלת ה־19, יותר ממאה שנה אחרי אחנתון. מצרים עדיין פועלת בכנען ושומרת על האינטרסים ועל הדרכים שלה באזור.",kind:"egypt",disputed:!1,sections:[]},{id:"exodus",title:"מסורת העבדות ויציאת מצרים",reference:"בערך 1270–1250 לפנה״ס",body:"יש חוקרים ומסורות שממקמים תיארוך “מאוחר” של יציאת מצרים סביב ימי רעמסס השני. אין הסכמה מחקרית על תאריך יציאה, ואף אין מקור מצרי ישיר המאשר את סיפור העבדות או היציאה כפי שהוא במקרא.",takeaway:"זו הצעה לתיארוך המסורת — לא עובדה היסטורית מוכחת.",kind:"israel",disputed:!0,sections:[]},{id:"merneptah",title:"מרנפתח ומצבת ישראל",reference:"בערך 1208 לפנה״ס",body:"מרנפתח, בנו של רעמסס השני, מתאר מסע בכנען ומזכיר את אשקלון, גזר, ינעם וישראל. הערים מסומנות כיישובים; ישראל מסומנת כעם.",takeaway:"האזכור החוץ־מקראי הקדום ביותר של “ישראל”.",kind:"egypt",disputed:!1,sections:[]},{id:"highlands",title:"ראשית ישראל בהר המרכזי",reference:"סוף המאה ה־13–המאה ה־12 לפנה״ס",body:"בארכאולוגיה ניכרת התרחבות של יישובים כפריים בהר המרכזי. בתוך העולם הכנעני המשתנה מתגבשות קבוצות שמהן יתפתח בהמשך עם ישראל.",kind:"israel",disputed:!1,sections:[]}]}]])}]);